export interface PageBlock {
  type: PageBlockType;
  text?: string;
  hi?: string;
  label?: { text: string; hi?: string };
  value?: { text: string; hi?: string };
  items?: any[];
  rows?: any[];
  columns?: any[];
  icon?: string;
}

export interface NativePage {
  title: string;
  content: PageBlock[];
}

